//! Clipboard capture validation and privacy filtering service (PRD FR-003 & Section 8).

use island_common::{IslandError, IslandResult};

/// Known pasteboard UTI / marker types indicating concealed or transient content (e.g. 1Password, Keychain).
const SENSITIVE_PASTEBOARD_MARKERS: &[&str] = &[
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
    "com.agilebits.onepassword",
    "de.anea.keepassmac.password",
];

#[derive(Debug, Clone)]
pub struct ClipboardCaptureCandidate {
    pub content_type: String,
    pub text_content: String,
    pub source_app: String,
    pub pasteboard_types: Vec<String>,
    pub is_secure_input_active: bool,
}

/// Validates and filters a clipboard capture candidate against privacy and security rules.
pub fn validate_clipboard_candidate(candidate: &ClipboardCaptureCandidate) -> IslandResult<()> {
    if candidate.is_secure_input_active {
        return Err(IslandError::PrivacyFiltered(
            "Clipboard capture blocked while macOS Secure Event Input is active".to_string(),
        ));
    }

    for pb_type in &candidate.pasteboard_types {
        if SENSITIVE_PASTEBOARD_MARKERS
            .iter()
            .any(|marker| pb_type.eq_ignore_ascii_case(marker))
        {
            return Err(IslandError::PrivacyFiltered(format!(
                "Clipboard item contains sensitive pasteboard marker: {pb_type}"
            )));
        }
    }

    if candidate.text_content.trim().is_empty() {
        return Err(IslandError::Validation(
            "Clipboard text content must not be empty".to_string(),
        ));
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn blocks_secure_input_and_concealed_types() {
        let secure_candidate = ClipboardCaptureCandidate {
            content_type: "public.utf8-plain-text".to_string(),
            text_content: "my-secret".to_string(),
            source_app: "Terminal".to_string(),
            pasteboard_types: vec!["public.utf8-plain-text".to_string()],
            is_secure_input_active: true,
        };
        assert!(matches!(
            validate_clipboard_candidate(&secure_candidate),
            Err(IslandError::PrivacyFiltered(_))
        ));

        let concealed_candidate = ClipboardCaptureCandidate {
            content_type: "public.utf8-plain-text".to_string(),
            text_content: "hunter2".to_string(),
            source_app: "1Password".to_string(),
            pasteboard_types: vec![
                "public.utf8-plain-text".to_string(),
                "org.nspasteboard.ConcealedType".to_string(),
            ],
            is_secure_input_active: false,
        };
        assert!(matches!(
            validate_clipboard_candidate(&concealed_candidate),
            Err(IslandError::PrivacyFiltered(_))
        ));
    }
}
